fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut left: i32 = host::display::state_get(1);
    let mut flash: i32 = host::display::state_get(2);
    if down == 1 && prev == 0 && left == 0 {
        left = 300;
    }
    if left > 0 {
        left = left - 1;
        if left == 0 {
            host::audio::tone_at(988, 120, 1, 0);
            host::audio::tone_at(988, 120, 1, 200);
            host::audio::tone_at(1319, 400, 1, 400);
            flash = 24;
        }
    }
    if flash > 0 { flash = flash - 1; }
    host::display::state_set(0, down);
    host::display::state_set(1, left);
    host::display::state_set(2, flash);
    let mut bg: i32 = 0x101018;
    if flash > 0 && (flash / 4) % 2 == 0 { bg = 0xffffff; }
    host::display::clear(bg);
    if left > 0 {
        host::display::draw_number(220, 200, (left + 59) / 60, 0x00ffcc, 5);
        host::display::draw_string(180, 300, "COUNTING DOWN", 0x808080, 1);
    } else {
        host::display::draw_string(120, 220, "TAP = 5 SEC TIMER", 0xffffff, 2);
    }
    host::display::present();
}
